PRAGMA foreign_keys=ON;
CREATE TABLE metadata (key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE sources (id TEXT PRIMARY KEY,title TEXT NOT NULL,owner TEXT NOT NULL,url TEXT NOT NULL,licence TEXT NOT NULL,version TEXT,published_at TEXT,access_state TEXT NOT NULL,details_json TEXT NOT NULL);
CREATE TABLE source_files (id TEXT PRIMARY KEY,source_id TEXT NOT NULL REFERENCES sources(id),path TEXT UNIQUE NOT NULL,sha256 TEXT NOT NULL,bytes INTEGER NOT NULL,licence TEXT NOT NULL,acquired_at TEXT NOT NULL,details_json TEXT NOT NULL);
CREATE TABLE sheets (id TEXT PRIMARY KEY,file_id TEXT NOT NULL REFERENCES source_files(id),name TEXT NOT NULL,headers_json TEXT NOT NULL,UNIQUE(file_id,name));
CREATE TABLE source_rows (id TEXT PRIMARY KEY,sheet_id TEXT NOT NULL REFERENCES sheets(id),source_row INTEGER NOT NULL,raw_json TEXT NOT NULL,fingerprint TEXT NOT NULL,UNIQUE(sheet_id,source_row));
CREATE TABLE sites (id TEXT PRIMARY KEY,country TEXT NOT NULL,name TEXT NOT NULL,latitude REAL,longitude REAL,coordinate_support TEXT NOT NULL,system TEXT,source_id TEXT NOT NULL REFERENCES sources(id),CHECK(latitude IS NULL OR latitude BETWEEN -90 AND 90),CHECK(longitude IS NULL OR longitude BETWEEN -180 AND 180));
CREATE TABLE trials (id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites(id),design TEXT NOT NULL,background_json TEXT NOT NULL,dependency_group TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES sources(id));
CREATE TABLE blocks (id TEXT PRIMARY KEY,trial_id TEXT NOT NULL REFERENCES trials(id),source_label TEXT NOT NULL,UNIQUE(trial_id,source_label));
CREATE TABLE treatments (id TEXT PRIMARY KEY,trial_id TEXT NOT NULL REFERENCES trials(id),source_label TEXT NOT NULL,is_control INTEGER NOT NULL CHECK(is_control IN(0,1)),control_definition TEXT NOT NULL,assignment_json TEXT NOT NULL,UNIQUE(trial_id,source_label));
CREATE TABLE plots (id TEXT PRIMARY KEY,trial_id TEXT NOT NULL REFERENCES trials(id),block_id TEXT REFERENCES blocks(id),treatment_id TEXT NOT NULL REFERENCES treatments(id),source_label TEXT NOT NULL,experimental_area_m2 REAL,sown_area_m2 REAL,harvested_area_m2 REAL,replication_basis TEXT NOT NULL,UNIQUE(trial_id,source_label),CHECK(experimental_area_m2 IS NULL OR experimental_area_m2>0));
CREATE TABLE crop_varieties (id TEXT PRIMARY KEY,crop TEXT NOT NULL,variety TEXT,source_id TEXT NOT NULL REFERENCES sources(id));
CREATE TABLE campaigns (id TEXT PRIMARY KEY,plot_id TEXT NOT NULL REFERENCES plots(id),variety_id TEXT REFERENCES crop_varieties(id),year INTEGER NOT NULL,season TEXT NOT NULL,sowing_date TEXT,harvest_date TEXT,date_precision TEXT NOT NULL,source_row_id TEXT NOT NULL REFERENCES source_rows(id),dependency_group TEXT NOT NULL,synthetic INTEGER NOT NULL DEFAULT 0 CHECK(synthetic IN(0,1)),UNIQUE(plot_id,year,season));
CREATE TABLE soil_profiles (id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites(id),plot_id TEXT REFERENCES plots(id),treatment_id TEXT REFERENCES treatments(id),year INTEGER,sampled_on TEXT,sampling_phase TEXT,upper_cm REAL,lower_cm REAL,sampling_support TEXT NOT NULL,source_row_id TEXT NOT NULL REFERENCES source_rows(id),licence TEXT NOT NULL,CHECK(upper_cm IS NULL OR lower_cm IS NULL OR (upper_cm>=0 AND lower_cm>upper_cm)));
CREATE TABLE soil_measurements (id TEXT PRIMARY KEY,profile_id TEXT NOT NULL REFERENCES soil_profiles(id),parameter TEXT NOT NULL,value REAL,unit TEXT NOT NULL,analytical_method TEXT NOT NULL,status TEXT NOT NULL,original_value TEXT,source_field TEXT NOT NULL,lower_class_bound REAL,upper_class_bound REAL,available_on TEXT,UNIQUE(profile_id,source_field));
CREATE TABLE campaign_soil_links (campaign_id TEXT NOT NULL REFERENCES campaigns(id),profile_id TEXT NOT NULL REFERENCES soil_profiles(id),temporal_basis TEXT NOT NULL,predictor_eligible INTEGER NOT NULL CHECK(predictor_eligible IN(0,1)),reason TEXT NOT NULL,PRIMARY KEY(campaign_id,profile_id));
CREATE TABLE weather_series (id TEXT PRIMARY KEY,site_id TEXT NOT NULL REFERENCES sites(id),variable TEXT NOT NULL,unit TEXT NOT NULL,time_step TEXT NOT NULL,spatial_support TEXT NOT NULL,source_id TEXT NOT NULL REFERENCES sources(id));
CREATE TABLE weather_observations (id TEXT PRIMARY KEY,series_id TEXT NOT NULL REFERENCES weather_series(id),period TEXT NOT NULL,value REAL,status TEXT NOT NULL,source_row_id TEXT NOT NULL REFERENCES source_rows(id),UNIQUE(series_id,period));
CREATE TABLE product_analyses (id TEXT PRIMARY KEY,trial_id TEXT NOT NULL REFERENCES trials(id),year INTEGER,crop TEXT,product TEXT NOT NULL,sampled_on TEXT,composition_json TEXT NOT NULL,method_json TEXT NOT NULL,source_row_id TEXT REFERENCES source_rows(id));
CREATE TABLE interventions (id TEXT PRIMARY KEY,plot_id TEXT NOT NULL REFERENCES plots(id),campaign_id TEXT REFERENCES campaigns(id),year INTEGER NOT NULL,season TEXT,date TEXT,date_precision TEXT NOT NULL,kind TEXT NOT NULL,product TEXT NOT NULL,dose REAL,unit TEXT NOT NULL,dose_basis TEXT NOT NULL,composition_id TEXT REFERENCES product_analyses(id),application_method TEXT,application_depth_cm REAL,status TEXT NOT NULL,source_row_id TEXT NOT NULL REFERENCES source_rows(id),CHECK(dose IS NULL OR dose>=0));
CREATE TABLE plant_observations (id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES campaigns(id),observed_on TEXT,parameter TEXT NOT NULL,value REAL,original_value TEXT,unit TEXT NOT NULL,method TEXT NOT NULL,sampling_unit TEXT NOT NULL,source_row_id TEXT NOT NULL REFERENCES source_rows(id));
CREATE TABLE harvests (id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES campaigns(id),event_label TEXT NOT NULL,harvested_on TEXT,organ TEXT NOT NULL,product_basis TEXT NOT NULL,moisture_percent REAL,area_m2 REAL,denominator TEXT NOT NULL,yield_value REAL,yield_unit TEXT,yield_kg_ha REAL,mass_kg REAL,status TEXT NOT NULL,source_row_id TEXT NOT NULL REFERENCES source_rows(id),UNIQUE(campaign_id,event_label));
CREATE TABLE response_functions (id TEXT PRIMARY KEY,country TEXT NOT NULL,crop TEXT NOT NULL,nutrient TEXT,year_text TEXT,source_identifier TEXT,latitude REAL,longitude REAL,a REAL,b REAL,c REAL,coefficient_units TEXT,original_json TEXT NOT NULL,source_row_id TEXT NOT NULL REFERENCES source_rows(id),excluded_from_plot_calibration INTEGER NOT NULL CHECK(excluded_from_plot_calibration=1));
CREATE TABLE context_observations (id TEXT PRIMARY KEY,country TEXT,crop TEXT,observation_kind TEXT NOT NULL,details_json TEXT NOT NULL,source_row_id TEXT NOT NULL REFERENCES source_rows(id),excluded_from_plot_calibration INTEGER NOT NULL CHECK(excluded_from_plot_calibration=1));
CREATE TABLE qc_issues (id INTEGER PRIMARY KEY,severity TEXT NOT NULL,code TEXT NOT NULL,record_id TEXT,field TEXT,message TEXT NOT NULL);
CREATE TABLE split_assignments (campaign_id TEXT PRIMARY KEY REFERENCES campaigns(id),split TEXT NOT NULL CHECK(split IN('train','validation','test')),protocol TEXT NOT NULL);
CREATE INDEX campaign_group ON campaigns(dependency_group);
CREATE INDEX soil_site ON soil_profiles(site_id,year);
CREATE INDEX harvest_campaign ON harvests(campaign_id);
-- Explicit labels, not an automatic training table. No imputation or nearest-profile join.
CREATE VIEW observation_units AS SELECT c.id,c.year,c.season,c.dependency_group,c.synthetic,s.country,v.crop,v.variety,p.source_label AS plot_label,p.experimental_area_m2,h.yield_kg_ha,h.denominator,h.moisture_percent,h.status AS harvest_status FROM campaigns c JOIN plots p ON p.id=c.plot_id JOIN trials t ON t.id=p.trial_id JOIN sites s ON s.id=t.site_id LEFT JOIN crop_varieties v ON v.id=c.variety_id LEFT JOIN harvests h ON h.campaign_id=c.id;
